package com.example.ancapp.ui

import android.content.Context
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.FhirExtractor
import com.example.ancapp.data.FhirRepository
import com.example.ancapp.data.PatientInfo
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class RegisterViewModel(context: Context) : ViewModel() {
  private val repository = FhirRepository(context)

  private val _patients = MutableStateFlow<List<PatientInfo>>(emptyList())
  val patients = _patients.asStateFlow()

  private val _isLoading = MutableStateFlow(false)
  val isLoading = _isLoading.asStateFlow()

  private val _error = MutableStateFlow<String?>(null)
  val error = _error.asStateFlow()

  fun loadPatients() {
    viewModelScope.launch {
      _isLoading.value = true
      _error.value = null
      try {
        repository.syncData()
        val patients = repository.getPatients()
        val patientInfos = patients.map { patient ->
          val dueDate = FhirExtractor.extractEstimatedDueDate(patient)
          FhirExtractor.extractPatientInfo(patient, dueDate)
        }.sortedBy { it.estimatedDueDate }
        _patients.value = patientInfos
      } catch (e: Exception) {
        _error.value = "Failed to load patients: ${e.message}"
      } finally {
        _isLoading.value = false
      }
    }
  }
}

