import com.example.ancapp.data.PatientInfo
import com.example.ancapp.data.formatBp
import com.example.ancapp.ui.PatientDetailViewModel
import java.time.format.DateTimeFormatter

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PatientDetailScreen(
  context: Context,
  patientId: String,
  onBackClick: () -> Unit,
  onAddVisitClick: () -> Unit,
) {
  val viewModel = PatientDetailViewModel(context)
  val patient = viewModel.patient.collectAsState().value
  val visits = viewModel.visits.collectAsState().value

  LaunchedEffect(patientId) {
    viewModel.loadPatient(patientId)
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text(patient?.name ?: "Patient") },
        navigationIcon = {
          IconButton(onBackClick) {
            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
          }
        },
      )
    },
    floatingActionButton = {
      FloatingActionButton(onAddVisitClick) {
        Icon(Icons.Default.Add, contentDescription = "Add Visit")
      }
    },
  ) { padding ->
    LazyColumn(modifier = Modifier
      .fillMaxSize()
      .padding(padding)) {
      item {
        if (patient != null) {
          PatientHeader(patient)
          HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp))
        }
      }

      item {
        Text(
          "Past ANC Visits",
          modifier = Modifier.padding(16.dp),
          style = MaterialTheme.typography.titleMedium,
          fontWeight = FontWeight.Bold,
        )
      }

      if (visits.isEmpty()) {
        item {
          Text(
            "No visits recorded yet.",
            modifier = Modifier.padding(16.dp),
            style = MaterialTheme.typography.bodySmall,
          )
        }
      } else {
        items(visits) { visit ->
          AncVisitCard(visit)
          HorizontalDivider()
        }
      }
    }
  }
}

@Composable
fun PatientHeader(patient: PatientInfo) {
  Column(modifier = Modifier.padding(16.dp)) {
    Text("Age: ${patient.age} years", style = MaterialTheme.typography.bodyMedium)
    if (patient.estimatedDueDate != null) {
      val formatter = DateTimeFormatter.ofPattern("MMM d, yyyy")
      Text(
        "Estimated Due Date: ${patient.estimatedDueDate.format(formatter)}",
        style = MaterialTheme.typography.bodyMedium,
      )
      patient.weeksOfPregnancy?.let {
        Text("Weeks of Pregnancy: $it weeks", style = MaterialTheme.typography.bodyMedium)
      }
    }
  }
}

@Composable
fun AncVisitCard(visit: AncVisit) {
  Column(modifier = Modifier
    .fillMaxWidth()
    .padding(16.dp)) {
    val dateFormatter = DateTimeFormatter.ofPattern("MMM d, yyyy")
    Text(
      "Visit: ${visit.date.format(dateFormatter)}",
      style = MaterialTheme.typography.titleSmall,
      fontWeight = FontWeight.Bold,
    )
    visit.gestationalAgeWeeks?.let {
      Text("Gestational Age: $it weeks", style = MaterialTheme.typography.bodySmall)
    }
