import com.example.ancapp.ui.NewVisitViewModel
import dev.ohs.fhir.datacapture.Questionnaire
import kotlinx.coroutines.launch

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NewVisitScreen(
  context: Context,
  patientId: String,
  onBackClick: () -> Unit,
  onVisitSaved: () -> Unit,
) {
  val viewModel = NewVisitViewModel(context)
  val questionnaireJson = viewModel.questionnaireJson.collectAsState().value
  val isSaving = viewModel.isSaving.collectAsState().value
  val saveSuccess = viewModel.saveSuccess.collectAsState().value
  val scope = rememberCoroutineScope()

  if (saveSuccess) {
    onVisitSaved()
    return
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("Record ANC Visit") },
        navigationIcon = {
          IconButton(onBackClick) {
            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
          }
        },
      )
    },
  ) { padding ->
    Box(modifier = Modifier.fillMaxSize()) {
      if (questionnaireJson == null) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
          CircularProgressIndicator()
        }
      } else {
        Questionnaire(
          questionnaireJson = questionnaireJson,
          onSubmit = { getResponse ->
            scope.launch {
              try {
                val response = getResponse()
                viewModel.saveVisit(patientId, response)
              } catch (e: Exception) {
                e.printStackTrace()
              }
            }
          },
          onCancel = onBackClick,
        )
      }

      if (isSaving) {
        Box(
          modifier = Modifier.fillMaxSize(),
          contentAlignment = Alignment.Center,
        ) {
          CircularProgressIndicator()
        }
      }
    }
  }
}

